package xray

import (
	"errors"
	"fmt"
	"sync"
)

// ConfigGenerator turns the abstract key-value config returned by HUE's
// NodeService.SyncConfig into the actual protocol-specific
// configuration the running xray-core process needs. Each transport
// profile (vless-xhttp, vless-ws, trojan-grpc, …) gets its own
// generator implementation; HUE doesn't decide which one to use, the
// embedding application picks one when constructing the Client.
//
// Generated bytes are typically the JSON body of an xray inbound that
// the adapter then ships to xray (via the HandlerService.AlterInbound
// RPC, by writing config to disk + SIGHUP, or however your deployment
// applies config — that's up to ApplyConfig).
type ConfigGenerator interface {
	// Name identifies the generator for logs and metrics.
	Name() string

	// Generate produces the protocol-specific config bytes from kv.
	// Returns an error when required keys are missing or values can't
	// be coerced. Implementations are pure: same input → same output.
	Generate(kv map[string]string) ([]byte, error)
}

// ApplyConfigFunc is how the adapter installs newly generated config
// onto the running xray process. The default in NewClient is a no-op
// (just logs); production deployments wire it to either an
// AlterInbound gRPC call or a "write file + SIGHUP" sequence,
// depending on how their xray runs.
type ApplyConfigFunc func(generated []byte) error

// ----------------------------------------------------------------------
// VlessXHTTP — a representative generator. Demonstrates the pattern;
// fork-and-modify for other transports.
// ----------------------------------------------------------------------

// VlessXHTTP generates a minimal vless inbound config with the xhttp
// transport. Required keys in kv:
//
//   port            uint16   listen port (e.g. "443")
//   user_uuid       string   the vless UUID
//   xhttp_path      string   the xhttp path (e.g. "/api")
//
// Optional keys:
//
//   xhttp_host      string   Host header / SNI (defaults to "")
//   listen          string   bind address (defaults to "0.0.0.0")
//   tls_cert_pem    string   PEM-encoded cert; if set, TLS is enabled
//   tls_key_pem     string   PEM-encoded key
//
// Unknown keys are ignored — adapters can stuff additional metadata
// into kv without breaking older generators.
type VlessXHTTP struct{}

func (VlessXHTTP) Name() string { return "vless-xhttp" }

func (VlessXHTTP) Generate(kv map[string]string) ([]byte, error) {
	if kv == nil {
		return nil, errors.New("xray/vless-xhttp: nil kv")
	}

	port, ok := kv["port"]
	if !ok || port == "" {
		return nil, errors.New("xray/vless-xhttp: missing required key `port`")
	}
	uuid, ok := kv["user_uuid"]
	if !ok || uuid == "" {
		return nil, errors.New("xray/vless-xhttp: missing required key `user_uuid`")
	}
	path, ok := kv["xhttp_path"]
	if !ok || path == "" {
		return nil, errors.New("xray/vless-xhttp: missing required key `xhttp_path`")
	}

	listen := getOr(kv, "listen", "0.0.0.0")
	host := kv["xhttp_host"]

	tlsBlock := ""
	if cert := kv["tls_cert_pem"]; cert != "" {
		key := kv["tls_key_pem"]
		if key == "" {
			return nil, errors.New("xray/vless-xhttp: tls_cert_pem set but tls_key_pem missing")
		}
		// In real code we'd marshal via encoding/json; this concise
		// fmt.Sprintf is deliberate to keep the generator dep-free
		// and the diff readable when reading the generated JSON.
		tlsBlock = fmt.Sprintf(`,
      "security": "tls",
      "tlsSettings": {
        "certificates": [{
          "certificate": [%q],
          "key":         [%q]
        }]
      }`, cert, key)
	}

	out := fmt.Sprintf(`{
  "tag":      "vless-in",
  "listen":   %q,
  "port":     %s,
  "protocol": "vless",
  "settings": {
    "clients":    [{"id": %q, "flow": ""}],
    "decryption": "none"
  },
  "streamSettings": {
    "network": "xhttp",
    "xhttpSettings": {
      "host": %q,
      "path": %q
    }%s
  }
}`, listen, port, uuid, host, path, tlsBlock)

	return []byte(out), nil
}

func getOr(kv map[string]string, key, fallback string) string {
	if v, ok := kv[key]; ok && v != "" {
		return v
	}
	return fallback
}

// ----------------------------------------------------------------------
// Registry — embedding programs that need to pick a generator at
// runtime (e.g., based on a Service's configured transport) can
// register concrete implementations here and look them up by name.
// Optional — adapters that always know their generator at construction
// time can pass it directly to Config.Generator and ignore Registry.
// ----------------------------------------------------------------------

var (
	registryMu sync.RWMutex
	registry   = map[string]ConfigGenerator{
		"vless-xhttp": VlessXHTTP{},
	}
)

// RegisterGenerator makes g lookupable by name via Generator(name).
// Calling with the same name twice replaces the previous registration.
func RegisterGenerator(g ConfigGenerator) {
	registryMu.Lock()
	defer registryMu.Unlock()
	registry[g.Name()] = g
}

// Generator returns the registered generator for name, or nil.
func Generator(name string) ConfigGenerator {
	registryMu.RLock()
	defer registryMu.RUnlock()
	return registry[name]
}
